static Color stone=new Color(.53f,.55f,.54f),ivory=new Color(.65f,.61f,.51f),steel=new Color(.055f,.065f,.07f),wood=new Color(.20f,.13f,.075f),gold=new Color(.48f,.31f,.095f);
