return g.Save(Styles[style]+(far?" Far":" Near"));}
static GameObject Prefab(int style,bool end){var go=new GameObject(Styles[style]+(end?" Terminal Post":" 8m Boundary Module"));var near=new GameObject("Near");near.transform.SetParent(go.transform,false);var far=new GameObject("Far");far.transform.SetParent(go.transform,false);var rn=near.AddComponent<MeshRenderer>();near.AddComponent<MeshFilter>().sharedMesh=Build(style,false,end);var rf=far.AddComponent<MeshRenderer>();far.AddComponent<MeshFilter>().sharedMesh=Build(style,true,end);foreach(var rr in new[]{rn,rf}){rr.sharedMaterial=mat;rr.shadowCastingMode=ShadowCastingMode.Off;rr.receiveShadows=true;rr.lightProbeUsage=LightProbeUsage.Off;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;GameObjectUtility.SetStaticEditorFlags(rr.gameObject,StaticEditorFlags.BatchingStatic);}var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.025f,new[]{rn}),new LOD(.0035f,new[]{rf})});lod.localReferencePoint=new Vector3(end?0:4,.5f,0);lod.size=1.05f;var col=go.AddComponent<BoxCollider>();col.center=new Vector3(end?0:4,.50f,0);col.size=new Vector3(end?.27f:8,1.0f,.26f);var asset=PrefabUtility.SaveAsPrefabAsset(go,D+go.name+".prefab");UnityEngine.Object.DestroyImmediate(go);return asset;}
